import { test, expect } from '@playwright/test';

test.describe('Active Filters Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/search');
  });

  test('should display active filter tags when filters are applied', async ({ page }) => {
    await page.getByLabel('Category').selectOption('Electronics');
    await page.getByLabel('Brand').selectOption('Brand A');
    await page.getByRole('button', { name: 'Apply Filters' }).click();

    const filterTags = await page.getByRole('list', { name: 'Active Filters' }).locator('li');
    expect(await filterTags.count()).toBe(2);
    expect(await filterTags.nth(0).innerText()).toContain('Category: Electronics');
    expect(await filterTags.nth(1).innerText()).toContain('Brand: Brand A');
  });

  test('should not display any filter tags when no filters are applied', async ({ page }) => {
    const filterTags = await page.getByRole('list', { name: 'Active Filters' }).locator('li');
    expect(await filterTags.count()).toBe(0);
  });
});
